/**
 * Cascade behind `ProjectService.archiveProject`; returns the number of issues
 * it archived. Only live issues are stamped: rows archived earlier keep their
 * original `archivedAt`, and are not counted (the usage meter already excludes
 * them).
 */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        ...compact(livePredicate(issues.archivedAt, {})),
      ),
    )

